%[text] %[text:anchor:H_EBF96D6D] ## Second Derivatives
%[text] As discussed in [DefinitionSoln.m](file:./DefinitionSoln.m), the derivative is a linear operator. In particular, since the derivative of a function is another function, it is possible to take several derivatives in sequence:
%[text]{"align":"center"} ![A function f(x) is passed into a box labeled "Derivative" which returns a function f prime of x which is passed into a box labeled "Derivative" which returns a function f double prime of x](text:image:093f)
%[text] Let's assume the units of $f(x)${"altText":"f(x)"} are frogs and the units of $x${"altText":"x"} are feet. Then 
%[text]{"align":"center"} $f(x)${"altText":"f(x)"} is the number of frogs                                                        
%[text]{"align":"center"} $f'(x)${"altText":"f'(x)"} is the number of frogs per foot ($\\frac{\\text{frogs}}{\\text{foot}}${"altText":"(frogs)\/(foot)"})                               
%[text]{"align":"center"} $f^{\\prime \\prime}(x)${"altText":"f^(' ')(x)"} is the number of frogs per square foot ($\\frac{\\text{frogs/foot}}{\\text{foot}} = \\frac{\\text{frogs}}{\\text{foot}^2}${"altText":"(frogs\/foot)\/(foot) = (frogs)\/(foot^2)"})
%[text] ![Warning symbol](text:image:0882) **Notation for Higher Order Derivatives**
%[text] <u>Prime Notation</u>
%[text]{"align":"center"} $f(x)${"altText":"f(x)"}, $f'(x)${"altText":"f'(x)"}, $f''(x)${"altText":"f''(x)"}, $f'''(x)${"altText":"f'''(x)"}, $f^{(iv)}(x)${"altText":"f^((iv))(x)"}, $f^{(v)}(x)${"altText":"f^((v))(x)"}, $\\ldots${"altText":"..."}, $f^{(n)}(x)${"altText":"f^((n))(x)"}
%[text] <u>Differential Notation</u>
%[text]{"align":"center"} $f(x)${"altText":"f(x)"},     $\\frac{df}{dx}${"altText":"(df)\/(dx)"},     $\\frac{d^2f}{dx^2}${"altText":"(d^2f)\/(dx^2)"},     $\\frac{d^3f}{dx^3}${"altText":"(d^3f)\/(dx^3)"},     $\\frac{d^4f}{dx^4}${"altText":"(d^4f)\/(dx^4)"},     $\\frac{d^5f}{dx^5}${"altText":"(d^5f)\/(dx^5)"},     $\\ldots${"altText":"..."},     $\\frac{d^nf}{dx^n}${"altText":"(d^nf)\/(dx^n)"}
%[text] <u>Operator Notation</u>
%[text]{"align":"center"} $f(x)${"altText":"f(x)"}, $\\frac{d}{dx}\[f\]${"altText":"(d)\/(dx)\[f\]"}, $\\frac{d}{dx}\\left\[\\frac{d}{dx}\[f\]\\right\] = \\frac{d^2}{dx^2}\[f\]${"altText":"(d)\/(dx)\[(d)\/(dx)\[f\]\] = (d^2)\/(dx^2)\[f\]"}, $\\frac{d}{dx}\\left\[\\frac{d}{dx}\\left\[\\frac{d}{dx}\[f\]\\right\]\\right\] = \\frac{d^3}{dx^3}\[f\]${"altText":"(d)\/(dx)\[(d)\/(dx)\[(d)\/(dx)\[f\]\]\] = (d^3)\/(dx^3)\[f\]"}, $\\ldots${"altText":"..."}, $\\frac{d^n}{dx^n}\[f\]${"altText":"(d^n)\/(dx^n)\[f\]"}
%%
%[text] ![](text:image:4bb2) **Exercise 3**.
%[text] The notation for the $n^{\\text{th}}${"altText":"n^(th)"} derivative of $g${"altText":"g"} with respect to $y${"altText":"y"} is $\\frac{d^ng}{dy^n}${"altText":"(d^ng)\/(dy^n)"} or $g^{(n)}(y)${"altText":"g^((n))(y)"} or $\\frac{d^n}{dy^n}\\left\[g\\right\]${"altText":"(d^n)\/(dy^n)\[g\]"}.
%[text] If the units of $g${"altText":"g"} are
gUnits = "C";            % User-defined string labeling units of dependent variable %[control:editfield:077f]{"position":[10,13]}
%[text] and the units of $y${"altText":"y"} are
yUnits = "m";            % User-defined string labeling units of independent variable %[control:editfield:063a]{"position":[10,13]}
                            % Run section %[control:button:6020]{"position":[1,2]}
if gUnits ~= "" && yUnits ~= ""           % Check for non-empty unit labels
    [n,opts] = SetOptions(gUnits,yUnits); % setOptions is defined in Helper Functions
    % setOptions sets up the unit options and selects the power n
    % for reference use in the drop-down menu dngdyn below
elseif (gUnits ~= "") && (yUnits == "")   % Prompt the user to enter a string in yUnits
    disp("You need to set values for the units of y to complete Exercise 3.")
elseif (gUnits == "") && (yUnits ~= "")   % Prompt the user to enter a string in gUnits
    disp("You need to set values for the units of g to complete Exercise 3.")
else                                      % Prompt the user to enter strings in both gUnits and yUnits
    disp("You need to set values for the units of g and the units of y to complete Exercise 3.")
end
%[text] **Solution:**
disp("The units of the nth derivative of g(y) are: Option "+n)
dngdyn = n; 
if dngdyn == 0                  % If the user has not changed the default value
    disp("It is possible to determine the units of the derivative.")
end
% Use a try/catch structure to replace "Unknown variables" error with constructive feedback
try                          % If the code inside the try generates an error, the catch block
    CheckGYUnits(dngdyn,n);  % executes rather than terminating the script with an error that
catch                        % throws the user out of "Hide Code" mode
    warning("You need to generate the problem in Exercise 3 before you can solve it.")
end
