%[text]        4\. Putting all of the facts established in Exercise 5, parts 1-3 together, identify the functional family of the derivative of the natural logarithm. 
% User-defined answer to "What type of function is the derivative of a natural logarithm?
lnDerGuessType = "rational"; %[control:dropdown:5097]{"position":[18,28]}
